#!/bin/bash
cd "$(dirname "$0")/.." || exit 1
while ! grep -q QUEUE_DONE build/agent_logs/queue6.log; do sleep 30; done
Q="ADD A QUADRUPED MODE to the giant phase 2 (variant 1) plus quadruped attacks (user request). Framework (already implemented, do not edit framework files): FpeEntity.getStance()/setStance(int) (0 normal, 1 quadruped; synced to the client; setStance calls refreshDimensions(), so make getDimensions() depend on getStance(): wider + lower in quad stance); AnimCtx.stance; in the bbmodel the animations 'quad_idle' and 'quad_walk' replace 'idle'/'walk' while stance==1; attacks stay ordinary ability ids (name quad ones quad_*; gate with .when(e -> e.getStance()==1) and the humanoid ones with stance==0; 'closer()' marks gap-closers). Also available: FpeEntity.meleeFocus()/engageRange(). Implement: (1) transition abilities drop_down / rise_up with their own animations, (2) switching logic in the Java class (e.g. goes on all fours when the target is far >9 blocks, when enraged, or randomly every ~200-400 ticks; moves faster on all fours via a temporary speed attribute modifier, returns upright when close or after a while), (3) a real quadruped gait: quad_idle (breathing, head low, tail sway) and quad_walk (all four limbs alternate, spine bobbing, hair/tentacles lag) - the arms must reach the ground in the quad pose, so adapt the rig/poses in tools/bbgen/chars/<name>.py, (4) at least 6 quadruped attacks, each with its own fully authored animation (e.g. ramming charge, pounce, double front-claw rake, tail sweep, tentacle/black eruption from the ground, bite lunge, stampede), flashy and rough. Keep all existing attacks working."
tools/run_agent.sh alice Alice "$Q Specs: 'alice' (phase 1) and 'alice_boss' (phase 2, the form that gets the quad mode); art docs/ref/confirmed/alice_phase2.jpg; only edit Alice.java, tools/bbgen/chars/alice.py (+ the regenerated bbmodels). The existing model must keep its look."
tools/run_agent.sh danger_alice DangerAlice "$Q Specs: 'danger_alice' (phase 1) and 'danger_alice_boss' (phase 2, the form that gets the quad mode); art docs/ref/confirmed/danger_alice_phase2.jpg; only edit DangerAlice.java, tools/bbgen/chars/danger_alice.py (+ the regenerated bbmodels). The existing model must keep its look."
echo QUEUE_DONE
